$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing;Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path (Split-Path $PSScriptRoot);$v='V10_Expression';$delivery=Join-Path $root 'Livraison'
function Details($path){$f=Get-Item -LiteralPath $path;$im=[System.Drawing.Image]::FromFile($f.FullName);$w=$im.Width;$h=$im.Height;$im.Dispose();[pscustomobject]@{File=[System.IO.Path]::GetRelativePath($root,$f.FullName);Width=$w;Height=$h;Bytes=$f.Length;SHA256=(Get-FileHash -LiteralPath $f.FullName).Hash}}
$exports=@(Get-ChildItem -LiteralPath (Join-Path $root ('Exports_4K\'+$v)) -Filter '*.png' -File);if($exports.Count -ne 1){throw 'Expected one final thumbnail'}
$export=Details $exports[0].FullName;$master=Details (Join-Path $root ('Masters\'+$v+'\09_Trading_In_3_Decisions_Expression_master.png'))
if($export.Width -ne 3840 -or $export.Height -ne 2160 -or $export.SHA256 -ne $master.SHA256){throw 'Dimensions or export integrity invalid'}
@($export,$master)|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $PSScriptRoot 'Final_manifest.csv')
foreach($row in (Import-Csv -LiteralPath (Join-Path $PSScriptRoot 'V09_baseline.csv'))){if((Get-FileHash -LiteralPath (Join-Path $root $row.File)).Hash -ne $row.SHA256){throw 'Previous V09 changed'}}
$sourceReport=foreach($row in (Import-Csv -LiteralPath (Join-Path (Split-Path $PSScriptRoot) 'Sources_HD_manifest_complet.csv'))){if((Get-FileHash -LiteralPath (Join-Path $root $row.File)).Hash -ne $row.SHA256){throw 'Original HD changed'};[pscustomobject]@{File=$row.File;Unchanged=$true}}
if(@($sourceReport).Count -ne 54){throw 'Expected 54 original stills'};$sourceReport|Export-Csv -NoTypeInformation -Encoding utf8 -LiteralPath (Join-Path $PSScriptRoot 'Original_sources_verified.csv')
$local=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'Local_edit_verification.json') -Raw|ConvertFrom-Json;if($local.ChangedPixelsOutsideFacialRegion -ne 0 -or $local.ChangedPixels -eq 0){throw 'Local edit invalid'}
$type=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'Typography_manifest.json') -Raw|ConvertFrom-Json;if($type.Text -ne 'Trading in 3 decisions.' -or $type.AddedGrain -or $type.X -lt 35 -or ($type.X+$type.TotalWidth) -gt 1245){throw 'Text check failed'}
function ZipCreate($path,$members,$flat=$false){if(Test-Path -LiteralPath $path){throw 'Archive exists'};$z=[System.IO.Compression.ZipFile]::Open($path,[System.IO.Compression.ZipArchiveMode]::Create);try{foreach($f in $members){$name=if($flat){$f.Name}else{[System.IO.Path]::GetRelativePath($root,$f.FullName).Replace('\','/')};$null=[System.IO.Compression.ZipFileExtensions]::CreateEntryFromFile($z,$f.FullName,$name,[System.IO.Compression.CompressionLevel]::Optimal)}}finally{$z.Dispose()}}
function ZipVerify($path,$members,$flat=$false){$z=[System.IO.Compression.ZipFile]::OpenRead($path);try{if($z.Entries.Count -ne $members.Count){throw 'ZIP count mismatch'};foreach($e in $z.Entries){$f=if($flat){$members|Where-Object {$_.Name -eq $e.Name}|Select-Object -First 1}else{Get-Item -LiteralPath (Join-Path $root $e.FullName)};$stream=$e.Open();$sha=[System.Security.Cryptography.SHA256]::Create();try{$hash=[Convert]::ToHexString($sha.ComputeHash($stream))}finally{$stream.Dispose();$sha.Dispose()};if($hash -ne (Get-FileHash -LiteralPath $f.FullName).Hash){throw 'ZIP payload mismatch'}};return $z.Entries.Count}finally{$z.Dispose()}}
$zip=Join-Path $delivery 'Casper_09_Expression_V10_3840x2160.zip';ZipCreate $zip $exports $true;$count=ZipVerify $zip $exports $true
$report=[ordered]@{Version=$v;Date=(Get-Date -Format 'yyyy-MM-dd');PNGCount=1;Width=3840;Height=2160;Native4K=$false;BaseDimensions='1672x941';AddedGrain=$false;OriginalSourcesUnchanged=54;PreviousV09Preserved=$true;LocalEdit=$local;Text=$type.Text;NativeTypography=$true;VisualReview='1280 and 320 previews, eye contact, speaking mouth, glasses, jaw continuity, hands and caption';ArchiveEntries=$count;ArchivePayloadHashesMatch=$true;ArchiveSHA256=(Get-FileHash -LiteralPath $zip).Hash};$report|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $PSScriptRoot 'Verification_V10.json') -Encoding utf8
$members=[System.Collections.Generic.List[System.IO.FileInfo]]::new();foreach($folder in @(('Masters\'+$v),('Exports_4K\'+$v),('Apercus\'+$v),('Suivi\'+$v),'References\Expression_V10','Suivi\Fonts')){foreach($f in (Get-ChildItem -LiteralPath (Join-Path $root $folder) -Recurse -File)){$members.Add($f)}}
foreach($path in @('LISEZ_MOI_V10_Expression.txt','Sources_HD\Casper\Casper_01-00-00.jpg')){$members.Add((Get-Item -LiteralPath (Join-Path $root $path)))}
$prod=Join-Path $delivery 'Casper_09_Expression_V10_Production.zip';ZipCreate $prod $members;$prodCount=ZipVerify $prod $members;$p=[pscustomobject]@{File=[System.IO.Path]::GetFileName($prod);Entries=$prodCount;AllPayloadHashesMatch=$true;Bytes=(Get-Item -LiteralPath $prod).Length;SHA256=(Get-FileHash -LiteralPath $prod).Hash};$p|ConvertTo-Json|Set-Content -LiteralPath (Join-Path $delivery 'Verification_Production_V10_Expression.json') -Encoding utf8
$report|ConvertTo-Json -Compress;$p|ConvertTo-Json -Compress
